﻿<script setup>
import { ref, computed, watch, onUnmounted } from 'vue';
import { BarChart3, Clock3, Minus, Plus, X } from 'lucide-vue-next';

const props = defineProps({
    isCreator: Boolean,
    activePoll: Object, // { id, question, options: [{text, count}], status: 'open'|'closed', createdAt, duration }
    pollResults: Object // { [optionIndex]: count } - calculated in parent or passed down
});

const emit = defineEmits(['create-poll', 'submit-vote', 'end-poll', 'close']);

// --- Creator State ---
const newQuestion = ref('');
const newOptions = ref([{ text: '' }, { text: '' }]); // Start with 2 options
const newDuration = ref(60); // Default 60 seconds

function addOption() {
    newOptions.value.push({ text: '' });
}

function removeOption(index) {
    if (newOptions.value.length > 2) {
        newOptions.value.splice(index, 1);
    }
}

function createPoll() {
    if (!newQuestion.value.trim()) return;
    const validOptions = newOptions.value.filter(o => o.text.trim());
    if (validOptions.length < 2) return;

    emit('create-poll', {
        question: newQuestion.value,
        options: validOptions.map(o => o.text),
        duration: newDuration.value
    });
    
    // Reset form
    newQuestion.value = '';
    newOptions.value = [{ text: '' }, { text: '' }];
    newDuration.value = 60;
}

function endPoll() {
    emit('end-poll');
}

// --- Participant State ---
const selectedOptionIndex = ref(null);
const hasVoted = ref(false);

// --- Timer Logic ---
const timeRemaining = ref(0);
let timerInterval = null;

function startTimer() {
    if (timerInterval) clearInterval(timerInterval);
    
    if (props.activePoll && props.activePoll.status === 'open' && props.activePoll.duration) {
        const endTime = props.activePoll.createdAt + (props.activePoll.duration * 1000);
        
        const update = () => {
            const now = Date.now();
            const left = Math.ceil((endTime - now) / 1000);
            timeRemaining.value = left > 0 ? left : 0;
            
            if (left <= 0) {
                clearInterval(timerInterval);
                // Auto-end if creator
                if (props.isCreator && props.activePoll.status === 'open') {
                    endPoll();
                }
            }
        };
        
        update(); // Initial call
        timerInterval = setInterval(update, 1000);
    } else {
        timeRemaining.value = 0;
    }
}

// Reset local state when poll changes
watch(() => props.activePoll?.id, (newId, oldId) => {
    if (newId !== oldId) {
        selectedOptionIndex.value = null;
        hasVoted.value = false;
        startTimer();
    }
});

// Also watch status to stop timer if manually ended
watch(() => props.activePoll?.status, (newStatus) => {
    if (newStatus === 'closed') {
        if (timerInterval) clearInterval(timerInterval);
        timeRemaining.value = 0;
    }
});

onUnmounted(() => {
    if (timerInterval) clearInterval(timerInterval);
});

function submitVote() {
    if (selectedOptionIndex.value === null) return;
    emit('submit-vote', selectedOptionIndex.value);
    hasVoted.value = true;
}

// --- Results Calculation (Display Helper) ---
const totalVotes = computed(() => {
    if (!props.pollResults) return 0;
    return Object.values(props.pollResults).reduce((a, b) => a + b, 0);
});

function getPercentage(index) {
    if (totalVotes.value === 0) return 0;
    const count = props.pollResults?.[index] || 0;
    return Math.round((count / totalVotes.value) * 100);
}
</script>

<template>
    <div class="polls-modal">
        <div class="modal-content">
            <div class="modal-header">
                <h3>استطلاع رأي</h3>
                <button class="close-btn" @click="$emit('close')">
                    <X :size="18" />
                </button>
            </div>

            <div class="modal-body">
                <!-- SCENE 1: CREATOR - CREATE NEW POLL -->
                <div v-if="isCreator && !activePoll" class="create-poll-form">
                    <h4>إنشاء استطلاع جديد</h4>
                    
                    <div class="form-group">
                        <label>السؤال</label>
                        <input v-model="newQuestion" type="text" placeholder="اكتب سؤالك هنا..." class="form-control" />
                    </div>

                    <div class="form-group">
                        <label>مدة الاستطلاع (ثانية)</label>
                        <input v-model.number="newDuration" type="number" min="10" class="form-control" />
                    </div>

                    <div class="options-list">
                        <label>الخيارات</label>
                        <div v-for="(opt, idx) in newOptions" :key="idx" class="option-input">
                            <input v-model="opt.text" type="text" :placeholder="`الخيار ${idx + 1}`" />
                            <button v-if="newOptions.length > 2" @click="removeOption(idx)" class="remove-btn">
                                <Minus :size="14" />
                            </button>
                        </div>
                        <button @click="addOption" class="add-btn">
                            <Plus :size="14" /> إضافة خيار
                        </button>
                    </div>

                    <div class="actions">
                        <button @click="createPoll" class="btn-primary" :disabled="!newQuestion.trim() || newOptions.filter(o=>o.text.trim()).length < 2 || newDuration < 5">
                            بدء الاستطلاع
                        </button>
                    </div>
                </div>

                <!-- SCENE 2: VOTING (Participant) -->
                <div v-else-if="activePoll && activePoll.status === 'open' && !isCreator && !hasVoted" class="voting-view">
                    <div class="poll-timer" v-if="timeRemaining > 0">
                        <Clock3 :size="14" /> {{ timeRemaining }}s
                    </div>
                    <h4>{{ activePoll.question }}</h4>
                    <div class="vote-options">
                        <label v-for="(opt, idx) in activePoll.options" :key="idx" class="radio-option">
                            <input type="radio" :value="idx" v-model="selectedOptionIndex" />
                            <span>{{ opt }}</span>
                        </label>
                    </div>
                    <button @click="submitVote" class="btn-primary" :disabled="selectedOptionIndex === null">
                        إرسال التصويت
                    </button>
                </div>

                <!-- SCENE 3: LIVE RESULTS (Creator or Voted Participant or Closed Poll) -->
                <div v-else-if="activePoll" class="results-view">
                    <div class="results-header">
                        <h4>{{ activePoll.question }}</h4>
                        <div class="header-badges">
                            <span v-if="activePoll.status === 'open' && timeRemaining > 0" class="timer-badge">
                                {{ timeRemaining }}s
                            </span>
                            <span class="status-badge" :class="activePoll.status">{{ activePoll.status === 'open' ? 'مباشر' : 'منتهي' }}</span>
                        </div>
                    </div>

                    <div class="results-list">
                        <div v-for="(opt, idx) in activePoll.options" :key="idx" class="result-item">
                            <div class="result-label">
                                <span>{{ opt }}</span>
                                <span>{{ props.pollResults?.[idx] || 0 }} صوت ({{ getPercentage(idx) }}%)</span>
                            </div>
                            <div class="progress-bar-bg">
                                <div class="progress-bar-fill" :style="{ width: getPercentage(idx) + '%' }"></div>
                            </div>
                        </div>
                    </div>

                    <div class="total-votes">
                        إجمالي الأصوات: {{ totalVotes }}
                    </div>

                    <div v-if="isCreator && activePoll.status === 'open'" class="actions">
                        <button @click="endPoll" class="btn-danger">إنهاء الاستطلاع</button>
                    </div>
                </div>


                <!-- SCENE 4: EMPTY STATE (Participant, no poll) -->
                <div v-else class="empty-state">
                    <BarChart3 :size="42" />
                    <p>لا يوجد استطلاع نشط حالياً.</p>
                </div>
            </div>
        </div>
    </div>
</template>

<style scoped>
.polls-modal {
    position: absolute;
    top: 0;
    left: 0;
    right: 90px;
    bottom: 0;
    background: rgba(0, 0, 0, 0.6); /* Dimmer background, not full overlay like resources */
    display: flex;
    justify-content: center;
    align-items: center; /* Center Vertically */
    z-index: 50; /* Higher than sidebar */
    pointer-events: none; /* Let clicks pass through outside */
    direction: rtl; /* RTL Support */
}

@media (max-width: 1024px) {
    .polls-modal {
        right: 0;
    }
}

.modal-content {
    pointer-events: auto;
    width: 400px;
    background: var(--ov-panel-bg, #1e1e1e);
    border-radius: 12px;
    display: flex;
    flex-direction: column;
    box-shadow: 0 10px 25px rgba(0,0,0,0.5);
    border: 1px solid var(--ov-panel-border, #333);
    max-height: 80vh;
    overflow: hidden;
    text-align: right; /* Align text right */
}

.modal-header {
    padding: 15px 20px;
    background: color-mix(in srgb, var(--ov-panel-bg, #252525) 88%, #000);
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--ov-panel-border, #333);
    flex-direction: row-reverse; /* Icons on left, text on right for RTL header */
}

.modal-header h3 {
    margin: 0;
    color: var(--ov-text, white);
    font-size: 1.1rem;
}

.close-btn {
    background: none;
    border: none;
    color: var(--ov-muted, #aaa);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}
.close-btn:hover { color: var(--ov-text, white); }

.modal-body {
    padding: 20px;
    overflow-y: auto;
    color: var(--ov-text, #eee);
}

/* Forms */
.form-group {
    margin-bottom: 15px;
}
.form-control, .option-input input {
    width: 100%;
    background: var(--ov-input-bg, #333);
    border: 1px solid var(--ov-input-border, #444);
    color: var(--ov-text, white);
    padding: 8px 12px;
    border-radius: 6px;
    margin-top: 5px;
    text-align: right;
}
.form-control:focus, .option-input input:focus {
    outline: none;
    border-color: #007bff;
}

.options-list {
    margin-bottom: 20px;
}
.option-input {
    display: flex;
    gap: 8px;
    margin-bottom: 8px;
}
.remove-btn, .add-btn {
    background: none;
    border: none;
    color: var(--ov-muted, #888);
    cursor: pointer;
    padding: 0 5px;
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
.remove-btn:hover { color: #ff4444; }
.add-btn {
    color: #007bff;
    font-size: 0.9rem;
    padding: 5px 0;
}
.add-btn:hover { text-decoration: underline; }

.btn-primary {
    width: 100%;
    padding: 10px;
    background: #007bff;
    border: none;
    border-radius: 6px;
    color: white;
    font-weight: 600;
    cursor: pointer;
}
.btn-primary:disabled {
    background: color-mix(in srgb, var(--ov-text, #ffffff) 20%, transparent);
    cursor: not-allowed;
}
.btn-danger {
    width: 100%;
    padding: 10px;
    background: #dc3545;
    border: none;
    border-radius: 6px;
    color: white;
    font-weight: 600;
    cursor: pointer;
}

/* Voting View */
.vote-options {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 20px;
}
.radio-option {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px;
    background: color-mix(in srgb, var(--ov-text, #ffffff) 10%, transparent);
    border-radius: 6px;
    cursor: pointer;
}
.radio-option:hover { background: color-mix(in srgb, var(--ov-text, #ffffff) 16%, transparent); }
.radio-option input { 
    accent-color: #007bff; 
    margin-left: 10px; /* Space for RTL */
}

/* Results View */
.results-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    flex-direction: row-reverse; /* Flip specific items if needed, or just let RTL handle */
}
.status-badge {
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: bold;
}
.status-badge.open { background: #28a745; color: white; }
.status-badge.closed { background: #6c757d; color: white; }

.result-item {
    margin-bottom: 12px;
}
.result-label {
    display: flex;
    justify-content: space-between;
    font-size: 0.9rem;
    margin-bottom: 4px;
    /* Ensure vote count is on left */
    flex-direction: row; 
}
.progress-bar-bg {
    height: 8px;
    background: color-mix(in srgb, var(--ov-text, #ffffff) 10%, transparent);
    border-radius: 4px;
    overflow: hidden;
    direction: ltr; /* Bars should still grow from left or right? Usually left even in RTL/Arabic UI contexts for progress bars unless mirrored. Let's keep LTR for bar fill visual or mirror it. */
}
/* For RTL progress bar, width fills from Right to Left if dir=rtl. If we want standard left-to-right fill, force LTR. */
.progress-bar-fill {
    height: 100%;
    background: #007bff;
    transition: width 0.5s ease;
}

.total-votes {
    text-align: left; /* Or right? */
    text-align: right;
    font-size: 0.85rem;
    color: var(--ov-muted, #888);
    margin-top: 10px;
    margin-bottom: 20px;
}

.empty-state {
    text-align: center;
    padding: 40px 20px;
    color: var(--ov-muted, #666);
}
.empty-state :deep(svg) {
    margin-bottom: 15px;
}
</style>

