source:
﻿<template>
    <div class="flex flex-col gap-5 p-5 w-full min-h-full bg-surface-50 dark:bg-surface-950">

        <!-- â”€â”€ Header â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -->
        <div class="rounded-2xl border border-surface-200 dark:border-surface-800 bg-surface-0 dark:bg-surface-900 shadow-sm overflow-hidden">
            <div class="h-1 bg-gradient-to-l from-blue-600 to-blue-800"></div>
            <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 px-4 py-3">
                <div class="flex items-center gap-3">
                    <div class="w-10 h-10 rounded-xl bg-primary flex items-center justify-center shrink-0">
                        <BookOpen class="w-5 h-5 text-white" />
                    </div>
                    <div>
                        <h1 class="text-xl font-bold text-surface-900 dark:text-surface-0 leading-tight">
                            {{ $t('sis.assignment.myAssignments') }}
                        </h1>
                        <p class="text-xs text-surface-500 dark:text-surface-400">
                            {{ $t('sis.assignment.myAssignmentsDesc') }}
                        </p>
                    </div>
                </div>
                <div class="relative w-full sm:w-64">
                    <Search class="w-3.5 h-3.5 absolute start-3 top-1/2 -translate-y-1/2 text-surface-400" />
                    <InputText
                        v-model="store.studentFilterSearch"
                        :placeholder="$t('sis.assignment.searchPlaceholder')"
                        class="h-9 ps-9 w-full text-sm rounded-lg border-surface-200 dark:border-surface-700"
                    />
                </div>
            </div>
        </div>

        <!-- â”€â”€ Stats Row â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -->
        <div class="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <button
                v-for="tab in tabs"
                :key="tab.key"
                type="button"
                :class="[
                    'flex flex-col items-start gap-1 p-4 rounded-2xl border font-medium text-sm transition-all text-start',
                    activeTab === tab.key
                        ? tab.activeClass
                        : 'bg-surface-0 dark:bg-surface-900 border-surface-200 dark:border-surface-700 hover:border-primary/50',
                ]"
                @click="setTab(tab.key)"
            >
                <div class="flex items-center justify-between w-full">
                    <component :is="tab.icon" :class="['w-4 h-4', activeTab === tab.key ? 'opacity-90' : 'text-surface-400 dark:text-surface-500']" />
                    <span :class="['text-2xl font-bold leading-none', activeTab === tab.key ? '' : 'text-surface-700 dark:text-surface-200']">
                        {{ String(tab.count).padStart(2, '0') }}
                    </span>
                </div>
                <span :class="activeTab === tab.key ? '' : 'text-surface-500 dark:text-surface-400'">
                    {{ tab.label }}
                </span>
            </button>
        </div>

        <!-- â”€â”€ Filters Row â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -->
        <div class="flex flex-wrap items-center gap-2 rounded-2xl border border-surface-200 dark:border-surface-800 bg-surface-0 dark:bg-surface-900 px-3 py-2 shadow-sm">
            <Select
                v-model="store.studentFilterCourseSemesterId"
                :options="courseSemesterOptions"
                optionLabel="label"
                optionValue="value"
                :placeholder="$t('sis.assignment.allCourses')"
                :loading="store.studentCourseSemestersLoading"
                showClear
                class="h-8 text-sm min-w-[180px]"
            />
            <div class="ms-auto flex items-center gap-1.5 text-xs text-surface-400 dark:text-surface-500">
                <ArrowUpDown class="w-3.5 h-3.5" />
                <Select
                    v-model="sortOrder"
                    :options="sortOptions"
                    optionLabel="label"
                    optionValue="value"
                    class="h-8 text-xs min-w-[160px] border-0 bg-transparent"
                />
            </div>
        </div>

        <!-- â”€â”€ Loading â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -->
        <div v-if="store.loading" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <div v-for="n in 6" :key="n" class="h-52 bg-surface-100 dark:bg-surface-800 rounded-2xl animate-pulse" />
        </div>

        <!-- â”€â”€ Cards Grid â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -->
        <div v-else-if="pagedAssignments.length > 0" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <div
                v-for="a in pagedAssignments"
                :key="a.id"
                class="group relative bg-surface-0 dark:bg-surface-900 rounded-2xl border border-surface-200 dark:border-surface-700 flex flex-col overflow-hidden cursor-pointer transition-all hover:shadow-lg hover:-translate-y-0.5 hover:border-primary/40 dark:hover:border-primary/40"
                @click="navigateToDetail(a)"
            >
                <!-- Top accent stripe -->
                <div :class="['h-1 w-full', statusStripeClass(a)]" />

                <div class="flex flex-col gap-3 p-4 flex-1">
                    <!-- Header row: badge + kind icon -->
                    <div class="flex items-center justify-between gap-2">
                        <span :class="['inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wide', statusBadgeClass(a)]">
                            <span :class="['w-1.5 h-1.5 rounded-full', statusDotClass(a)]" />
                            {{ statusBadgeLabel(a) }}
                        </span>
                        <div class="flex items-center gap-1">
                            <component
                                :is="a.assignmentKind === 1 ? Users : User"
                                class="w-3.5 h-3.5 text-surface-300 dark:text-surface-600"
                            />
                        </div>
                    </div>

                    <!-- Title + Course -->
                    <div class="flex-1">
                        <h3 class="font-semibold text-surface-900 dark:text-surface-0 text-sm leading-snug line-clamp-2 mb-1.5 group-hover:text-primary transition-colors">
                            {{ a.title }}
                        </h3>
                        <div class="flex items-center gap-1 text-[11px] text-surface-400 dark:text-surface-500">
                            <GraduationCap class="w-3 h-3 shrink-0" />
                            <span class="truncate">{{ a.courseName }}</span>
                        </div>
                    </div>

                    <!-- Score or Due Date -->
                    <div>
                        <!-- Graded -->
                        <template v-if="a.hasSubmitted && a.mySubmissionStatus === 2 && a.myScore !== null && a.isGradePublished">
                            <div class="flex items-center gap-2">
                                <div class="flex items-end gap-1">
                                    <span class="text-xl font-bold text-emerald-500 leading-none">{{ a.myScore }}</span>
                                    <span class="text-xs text-surface-400 mb-0.5">/{{ a.totalMarks }}</span>
                                </div>
                                <span v-if="scoreGrade(a)" class="px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 text-xs font-bold">
                                    {{ scoreGrade(a) }}
                                </span>
                            </div>
                        </template>
                        <!-- Submitted -->
                        <template v-else-if="a.hasSubmitted">
                            <div class="flex items-center gap-1.5 text-[11px] text-emerald-600 dark:text-emerald-400 font-medium">
                                <CheckCircle2 class="w-3.5 h-3.5" />
                                {{ $t('sis.assignment.submittedOn', { date: formatDateShort(a.mySubmittedAt) }) }}
                            </div>
                        </template>
                        <!-- Pending -->
                        <template v-else>
                            <div class="flex flex-col gap-0.5">
                                <div class="flex items-center gap-1.5 text-[11px] font-medium" :class="dueDateClass(a.effectiveDueDate ?? a.dueDate)">
                                    <Clock class="w-3.5 h-3.5" />
                                    {{ dueDateText(a) }}
                                </div>
                                <span v-if="a.effectiveDueDate && a.effectiveDueDate !== a.dueDate"
                                    class="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded-md text-[9px] font-bold bg-violet-100 dark:bg-violet-900/30 text-violet-600 dark:text-violet-400 uppercase tracking-wide w-fit">
                                    {{ $t('sis.assignment.overrideBadge') }}
                                </span>
                            </div>
                        </template>
                    </div>
                </div>

                <!-- Footer -->
                <div class="flex items-center justify-between gap-2 px-4 py-2.5 border-t border-surface-100 dark:border-surface-800 bg-surface-50/50 dark:bg-surface-800/30">
                    <div class="flex items-center gap-1 text-[11px] text-surface-400">
                        <Trophy class="w-3 h-3" />
                        <span class="font-semibold text-surface-600 dark:text-surface-300">{{ a.totalMarks }}</span>
                        <span>{{ $t('sis.assignment.pts') }}</span>
                    </div>
                    <button
                        type="button"
                        :class="ctaButtonClass(a)"
                        @click.stop="handleCta(a)"
                    >
                        {{ ctaLabel(a) }}
                    </button>
                </div>
            </div>
        </div>

        <!-- â”€â”€ Empty State â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -->
        <div v-else class="flex flex-col items-center justify-center py-20 gap-4 text-center">
            <div class="w-16 h-16 rounded-2xl bg-surface-100 dark:bg-surface-800 flex items-center justify-center">
                <BookOpen class="w-7 h-7 text-surface-300 dark:text-surface-600" />
            </div>
            <div>
                <p class="font-semibold text-surface-600 dark:text-surface-400 mb-1">{{ emptyTitle }}</p>
                <p class="text-sm text-surface-400 dark:text-surface-500 max-w-xs mx-auto">{{ emptyDesc }}</p>
            </div>
        </div>

        <!-- â”€â”€ Load More â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -->
        <div v-if="!store.loading && filteredList.length > visibleCount" class="flex justify-center">
            <button
                type="button"
                class="flex items-center gap-2 px-5 py-2.5 rounded-xl border border-surface-200 dark:border-surface-700 text-sm font-medium text-surface-600 dark:text-surface-300 hover:bg-surface-100 dark:hover:bg-surface-800 transition-colors"
                @click="visibleCount += 9"
            >
                <ChevronDown class="w-4 h-4" />
                {{ $t('sis.assignment.loadMore') }}
            </button>
        </div>

    </div>
</template>

<script setup>
import { ref, computed, onMounted, watch } from "vue";
import { useRouter } from "vue-router";
import { useI18n } from "vue-i18n";
import {
    BookOpen, Search, User, Users, ChevronDown, Clock, Trophy,
    CheckCircle2, GraduationCap, ArrowUpDown, ListTodo, CheckCheck, Star, LayoutGrid,
} from "lucide-vue-next";
import { useAssignmentStore } from "../../stores/assignmentStore.js";

const router = useRouter();
const { t } = useI18n();
const store = useAssignmentStore();

// â”€â”€ Tabs â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const activeTab = ref("all");

const tabs = computed(() => [
    {
        key: "all",
        label: t("sis.assignment.tabAll"),
        count: store.studentAssignments.length,
        icon: LayoutGrid,
        activeClass: "bg-primary/10 border-primary/30 text-primary dark:text-primary-300",
    },
    {
        key: "pending",
        label: t("sis.assignment.tabPending"),
        count: store.studentPendingCount,
        icon: ListTodo,
        activeClass: "bg-amber-500/10 border-amber-400/30 text-amber-700 dark:text-amber-400",
    },
    {
        key: "submitted",
        label: t("sis.assignment.tabSubmitted"),
        count: store.studentSubmittedCount,
        icon: CheckCheck,
        activeClass: "bg-emerald-500/10 border-emerald-400/30 text-emerald-700 dark:text-emerald-400",
    },
    {
        key: "graded",
        label: t("sis.assignment.tabGraded"),
        count: store.studentGradedCount,
        icon: Star,
        activeClass: "bg-blue-500/10 border-blue-400/30 text-blue-700 dark:text-blue-400",
    },
]);

function setTab(key) {
    activeTab.value = key;
    store.studentFilterStatus = key === "all" ? null : key;
}

// â”€â”€ Filters â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const sortOrder = ref("dueDate");

const courseSemesterOptions = computed(() =>
    store.studentCourseSemesters.map((cs) => ({
        label: cs.courseTitle ?? `ID: ${cs.id}`,
        value: cs.id,
    }))
);

const sortOptions = computed(() => [
    { label: t("sis.assignment.sortByDueDate"), value: "dueDate" },
]);

// â”€â”€ Filtered & Sorted List â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const filteredList = computed(() => {
    let list = [...store.filteredStudentAssignments];
    list.sort((a, b) => new Date(a.effectiveDueDate ?? a.dueDate) - new Date(b.effectiveDueDate ?? b.dueDate));
    return list;
});

// â”€â”€ Pagination â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const visibleCount = ref(9);
const pagedAssignments = computed(() => filteredList.value.slice(0, visibleCount.value));

watch([() => store.studentFilterSearch, () => store.studentFilterCourseSemesterId, () => store.studentFilterStatus], () => {
    visibleCount.value = 9;
});

// â”€â”€ Empty State â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const emptyTitle = computed(() => {
    switch (activeTab.value) {
        case "pending":   return t("sis.assignment.noPendingAssignments");
        case "submitted": return t("sis.assignment.noSubmittedAssignments");
        case "graded":    return t("sis.assignment.noGradedAssignments");
        default:          return t("sis.assignment.noStudentAssignments");
    }
});

const emptyDesc = computed(() => {
    switch (activeTab.value) {
        case "pending":   return t("sis.assignment.noPendingDesc");
        case "submitted": return t("sis.assignment.noSubmittedDesc");
        case "graded":    return t("sis.assignment.noGradedDesc");
        default:          return t("sis.assignment.noStudentAssignmentsDesc");
    }
});

// â”€â”€ Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function isOverdue(dateStr) { return dateStr && new Date(dateStr) < new Date(); }
function formatDateShort(dateStr) {
    if (!dateStr) return "";
    return new Date(dateStr).toLocaleDateString(undefined, { month: "short", day: "numeric" });
}
function dueDiffDays(dateStr) {
    if (!dateStr) return null;
    return Math.ceil((new Date(dateStr) - new Date()) / 86400000);
}
function dueDateText(a) {
    const days = dueDiffDays(a.effectiveDueDate ?? a.dueDate);
    if (days === null) return "";
    if (days < 0) return t("sis.assignment.overdueBy", { h: Math.abs(days * 24) });
    if (days === 0) return t("sis.assignment.dueToday");
    return t("sis.assignment.dueIn", { n: days });
}
function dueDateClass(dateStr) {
    const days = dueDiffDays(dateStr);
    if (days === null) return "text-surface-400";
    if (days < 0) return "text-red-500 dark:text-red-400";
    if (days <= 2) return "text-amber-500 dark:text-amber-400";
    return "text-surface-500 dark:text-surface-400";
}
function scoreGrade(a) {
    if (a.myScore == null || !a.totalMarks) return null;
    const pct = (a.myScore / a.totalMarks) * 100;
    if (pct >= 90) return "A"; if (pct >= 80) return "B";
    if (pct >= 70) return "C"; if (pct >= 60) return "D"; return "F";
}

// Status visuals
function effectiveDue(a) { return a.effectiveDueDate ?? a.dueDate; }
function statusStripeClass(a) {
    if (a.hasSubmitted && a.mySubmissionStatus === 2) return "bg-blue-500";
    if (a.hasSubmitted) return "bg-emerald-500";
    if (a.status === 2 || (!a.hasSubmitted && isOverdue(effectiveDue(a)))) return "bg-red-400";
    return "bg-amber-400";
}
function statusDotClass(a) {
    if (a.hasSubmitted && a.mySubmissionStatus === 2) return "bg-blue-500";
    if (a.hasSubmitted) return "bg-emerald-500";
    if (a.status === 2 || (!a.hasSubmitted && isOverdue(effectiveDue(a)))) return "bg-red-500";
    return "bg-amber-500";
}
function statusBadgeLabel(a) {
    if (a.hasSubmitted && a.mySubmissionStatus === 2) return t("sis.assignment.badgeGraded");
    if (a.hasSubmitted) return t("sis.assignment.badgeSubmitted");
    if (a.status === 2 || (!a.hasSubmitted && isOverdue(effectiveDue(a)))) return t("sis.assignment.badgeClosed");
    return t("sis.assignment.badgePending");
}
function statusBadgeClass(a) {
    if (a.hasSubmitted && a.mySubmissionStatus === 2) return "bg-blue-500/10 text-blue-600 dark:text-blue-400";
    if (a.hasSubmitted) return "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400";
    if (a.status === 2 || (!a.hasSubmitted && isOverdue(effectiveDue(a)))) return "bg-red-500/10 text-red-600 dark:text-red-400";
    return "bg-amber-500/10 text-amber-600 dark:text-amber-400";
}
function ctaLabel(a) {
    if (a.hasSubmitted && a.mySubmissionStatus === 2) return t("sis.assignment.viewFeedback");
    if (a.hasSubmitted) return t("sis.assignment.editDraft");
    if (a.status === 2 || (!a.hasSubmitted && isOverdue(effectiveDue(a)))) return t("sis.assignment.lateSubmission");
    return t("sis.assignment.submitAssignment");
}
function ctaButtonClass(a) {
    const base = "px-3 py-1 rounded-lg text-xs font-semibold transition-colors whitespace-nowrap";
    if (a.status === 2 || (!a.hasSubmitted && isOverdue(effectiveDue(a)))) return `${base} bg-surface-100 dark:bg-surface-800 text-surface-400 cursor-default`;
    if (a.hasSubmitted) return `${base} bg-surface-100 dark:bg-surface-800 text-surface-600 dark:text-surface-300 hover:bg-surface-200 dark:hover:bg-surface-700`;
    return `${base} bg-primary text-white hover:bg-primary-600 shadow-sm`;
}

// â”€â”€ Navigation â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function navigateToDetail(a) {
    router.push({ name: "Student Assignment Detail", params: { id: a.id } });
}
function handleCta(a) {
    if (a.status === 2 && !a.hasSubmitted && isOverdue(effectiveDue(a))) return;
    navigateToDetail(a);
}

// â”€â”€ Lifecycle â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
onMounted(async () => {
    await Promise.all([
        store.getStudentAssignments(),
        store.getStudentCourseSemesters(),
    ]);
});
</script>

