source:
﻿<template>
    <div class="student-distribution-page">
        <div class="page-shell">
            <header class="page-header">
                <h1 class="page-title">{{ t("sis.studentDistribution.title") }}</h1>
                <p class="page-subtitle">{{ t("sis.studentDistribution.subtitle") }}</p>
            </header>

            <section class="config-card">
                <div class="field-group">
                    <label class="field-label">{{ t("sis.studentDistribution.fields.academicLevel") }}</label>
                    <Select
                        v-model="selectedAcademicLevelId"
                        :options="academicLevelOptions"
                        option-label="label"
                        option-value="value"
                        :placeholder="t('sis.studentDistribution.fields.selectAcademicLevel')"
                        :disabled="loadingFlag"
                        @change="handleAcademicLevelChange"
                    />
                </div>
                <div class="stats-grid">
                    <article class="stat-box">
                        <p class="stat-value">{{ totalStudents }}</p>
                        <p class="stat-label">{{ t("sis.studentDistribution.stats.totalStudents") }}</p>
                    </article>
                    <article class="stat-box">
                        <p class="stat-value">{{ groupsCount }}</p>
                        <p class="stat-label">{{ t("sis.studentDistribution.stats.groupsCount") }}</p>
                    </article>
                </div>
            </section>

            <section class="methods-grid">
                <button
                    v-for="method in methodCards"
                    :key="method.id"
                    type="button"
                    class="method-card"
                    :class="{ 'method-card--active': selectedMethod === method.id }"
                    @click="onSelectMethod(method.id)"
                >
                    <h3 class="method-title">{{ method.title }}</h3>
                    <p class="method-description">{{ method.description }}</p>
                </button>
            </section>

            <section class="simulation-card">
                <div class="simulation-header">
                    <div class="simulation-header-left">
                        <h2 class="simulation-title">{{ t("sis.studentDistribution.simulation.title") }}</h2>
                        <span class="simulation-badge" :class="{ 'simulation-badge--active': isSimulating }">
                            {{ simulationStatusText }}
                        </span>
                    </div>
                    <div class="actions-row">
                        <button type="button" class="btn btn-primary" @click="executeDistribution">
                            {{ t("sis.studentDistribution.actions.execute") }}
                        </button>
                        <button type="button" class="btn btn-secondary" @click="replaySimulation">
                            {{ t("sis.studentDistribution.actions.replay") }}
                        </button>
                    </div>
                </div>

                <div class="simulation-note">
                    {{ selectedMethodInfo.simulationNote }}
                </div>

                <p v-if="isManualMode" class="manual-hint">
                    {{ t("sis.studentDistribution.simulation.manualHint") }}
                </p>

                <div ref="boardRef" class="simulation-board">
                    <aside class="source-column">
                        <template v-for="section in sourceSections" :key="section.key">
                            <h3 class="source-title">{{ section.title }}</h3>
                            <div class="source-list">
                                <div
                                    v-for="slot in section.slots"
                                    :key="slot.slotId"
                                    :ref="(el) => setSourceSlotRef(el, slot.slotId)"
                                    class="source-slot"
                                >
                                    <div
                                        v-if="slot.state === SLOT_STATES.ready || slot.state === SLOT_STATES.animating"
                                        class="student-card"
                                        :class="{ 'student-card--ghost': slot.state === SLOT_STATES.animating }"
                                        :draggable="isManualMode"
                                        @dragstart="onSourceDragStart($event, slot)"
                                    >
                                        <span class="student-number">{{ formatStudentNumber(slot.student.seniority) }}</span>
                                        <span class="student-name">{{ slot.student.name }}</span>
                                    </div>
                                    <div v-else class="slot-placeholder" />
                                </div>
                            </div>
                        </template>
                    </aside>

                    <div class="groups-grid" :style="groupGridStyle">
                        <article
                            v-for="group in groups"
                            :key="group.id"
                            class="group-lane"
                            :class="`group-lane--${group.id}`"
                        >
                            <div class="group-pill">
                                {{ t("sis.studentDistribution.teamName", { number: group.id }) }}
                            </div>
                            <div
                                :ref="(el) => setGroupBodyRef(el, group.id)"
                                class="group-body"
                                @dragover="onGroupDragOver"
                                @drop="onDropToGroup($event, group.id)"
                            >
                                <div
                                    v-for="member in group.members"
                                    :key="`group-${group.id}-member-${member.id}`"
                                    class="group-member"
                                    :draggable="isManualMode"
                                    @dragstart="onGroupDragStart($event, group.id, member.id)"
                                >
                                    <span class="student-number">{{ formatStudentNumber(member.seniority) }}</span>
                                    <span class="student-name">{{ member.name }}</span>
                                </div>
                            </div>
                        </article>
                    </div>

                    <div
                        v-if="movingOverlay.visible && movingOverlay.student"
                        class="moving-card"
                        :style="movingCardStyle"
                    >
                        <span class="student-number">{{ formatStudentNumber(movingOverlay.student.seniority) }}</span>
                        <span class="student-name">{{ movingOverlay.student.name }}</span>
                    </div>
                </div>

                <p v-if="allDistributed" class="distribution-done">
                    {{ t("sis.studentDistribution.simulation.allDistributed") }}
                </p>
            </section>
        </div>
    </div>
</template>

<script setup>
import { useStudentDistributionStore } from "@/projects/sis/stores/studentDistributionStore";

const METHODS = Object.freeze({
    manual: 1,
    seniority: 2,
    collegeThenSeniority: 3,
});

const SLOT_STATES = Object.freeze({
    ready: "ready",
    animating: "animating",
    moving: "moving",
    moved: "moved",
});

const COLLEGE_ORDER = ["war", "navy", "air"];
const GROUP_COUNT = 3;
const MOVE_DURATION_MS = 800;
const STEP_DELAY_MS = 120;
const GROUP_CARD_HEIGHT = 52;
const GROUP_CARD_GAP = 10;

const SAMPLE_STUDENTS = [
    { id: 1, name: "أحمد السيد", seniority: 1, collegeKey: "war" },
    { id: 2, name: "محمد مصطفى", seniority: 2, collegeKey: "war" },
    { id: 3, name: "محمود عبد الله", seniority: 3, collegeKey: "war" },
    { id: 4, name: "عمر إبراهيم", seniority: 4, collegeKey: "war" },
    { id: 5, name: "يوسف حسن", seniority: 5, collegeKey: "war" },
    { id: 6, name: "كريم طارق", seniority: 6, collegeKey: "war" },

    { id: 7, name: "عبد الرحمن جمال", seniority: 7, collegeKey: "navy" },
    { id: 8, name: "مصطفى علي", seniority: 8, collegeKey: "navy" },
    { id: 9, name: "زياد أشرف", seniority: 9, collegeKey: "navy" },
    { id: 10, name: "أحمد سامح", seniority: 10, collegeKey: "navy" },
    { id: 11, name: "شريف ناصر", seniority: 11, collegeKey: "navy" },
    { id: 12, name: "إسلام فوزي", seniority: 12, collegeKey: "navy" },

    { id: 13, name: "مروان حسام", seniority: 13, collegeKey: "air" },
    { id: 14, name: "كريم حمدي", seniority: 14, collegeKey: "air" },
    { id: 15, name: "محمود ياسر", seniority: 15, collegeKey: "air" },
    { id: 16, name: "عمرو شوقي", seniority: 16, collegeKey: "air" },
    { id: 17, name: "طه رمضان", seniority: 17, collegeKey: "air" },
    { id: 18, name: "شادي مجدي", seniority: 18, collegeKey: "air" },
];

const distributionStore = useStudentDistributionStore();
const { t } = useI18n();
const toast = useToast();

const HARDCODED_ACADEMIC_LEVELS = [
    { id: 1, label: "القسم الاعدادى" },
    { id: 2, label: "القسم المتوسط" },
];

const selectedAcademicLevelId = ref(null);
const selectedMethod = ref(METHODS.seniority);
const loadingFlag = ref(false);
const isSimulating = ref(false);

const groups = ref([]);
const sourceSlots = ref([]);

const boardRef = ref(null);
const sourceSlotRefs = ref(new Map());
const groupBodyRefs = ref(new Map());
const dragPayload = ref(null);
const runToken = ref(0);

const movingOverlay = reactive({
    visible: false,
    student: null,
    top: 0,
    left: 0,
    width: 0,
    x: 0,
    y: 0,
});

const methodCards = computed(() => [
    {
        id: METHODS.manual,
        title: t("sis.studentDistribution.methods.manual.title"),
        description: t("sis.studentDistribution.methods.manual.description"),
        simulationNote: t("sis.studentDistribution.methods.manual.simulationNote"),
    },
    {
        id: METHODS.seniority,
        title: t("sis.studentDistribution.methods.seniority.title"),
        description: t("sis.studentDistribution.methods.seniority.description"),
        simulationNote: t("sis.studentDistribution.methods.seniority.simulationNote"),
    },
    {
        id: METHODS.collegeThenSeniority,
        title: t("sis.studentDistribution.methods.collegeThenSeniority.title"),
        description: t("sis.studentDistribution.methods.collegeThenSeniority.description"),
        simulationNote: t("sis.studentDistribution.methods.collegeThenSeniority.simulationNote"),
    },
]);

const academicLevelOptions = computed(() => flattenAcademicLevels(HARDCODED_ACADEMIC_LEVELS));
const selectedMethodInfo = computed(
    () => methodCards.value.find((method) => method.id === selectedMethod.value) || methodCards.value[0],
);

const isManualMode = computed(() => selectedMethod.value === METHODS.manual);
const isCollegeMode = computed(() => selectedMethod.value === METHODS.collegeThenSeniority);
const totalStudents = computed(() => sourceSlots.value.length);
const groupsCount = computed(() => groups.value.length);
const allDistributed = computed(() =>
    sourceSlots.value.length > 0 &&
    sourceSlots.value.every((slot) => slot.state !== SLOT_STATES.ready && slot.state !== SLOT_STATES.animating),
);
const simulationStatusText = computed(() =>
    isSimulating.value ? t("sis.studentDistribution.simulation.active") : t("sis.studentDistribution.simulation.ready"),
);

const sourceSections = computed(() => {
    if (!isCollegeMode.value) {
        return [{ key: "seniority", title: t("sis.studentDistribution.simulation.seniorityQueue"), slots: sourceSlots.value }];
    }

    return COLLEGE_ORDER.map((collegeKey) => ({
        key: collegeKey,
        title: t(`sis.studentDistribution.colleges.${collegeKey}`),
        slots: sourceSlots.value.filter((slot) => slot.collegeKey === collegeKey),
    }));
});

const movingCardStyle = computed(() => ({
    top: `${movingOverlay.top}px`,
    left: `${movingOverlay.left}px`,
    width: `${movingOverlay.width}px`,
    transform: `translate3d(${movingOverlay.x}px, ${movingOverlay.y}px, 0)`,
    transition: `transform ${MOVE_DURATION_MS}ms cubic-bezier(0.22, 1, 0.36, 1), width ${MOVE_DURATION_MS}ms cubic-bezier(0.22, 1, 0.36, 1)`,
}));

const groupGridStyle = computed(() => ({
    gridTemplateColumns: `repeat(${groups.value.length}, minmax(0, 1fr))`,
}));

onMounted(async () => {
    await loadAcademicLevels();
    if (selectedAcademicLevelId.value) {
        await fetchDistributionFlag(selectedAcademicLevelId.value);
    }
    await replaySimulation();
});

const flattenAcademicLevels = (levels, depth = 0, acc = []) => {
    levels.forEach((level) => {
        const value = Number(level.some_id ?? level.id ?? level.academicLevelId);
        const baseLabel = level.label || level.Title || level.title;
        if (!Number.isNaN(value) && baseLabel) {
            const prefix = depth > 0 ? `${"- ".repeat(depth)} ` : "";
            acc.push({ value, label: `${prefix}${baseLabel}`.trim() });
        }
        if (Array.isArray(level.children) && level.children.length) {
            flattenAcademicLevels(level.children, depth + 1, acc);
        }
    });
    return acc;
};

const createGroups = () =>
    Array.from({ length: GROUP_COUNT }, (_, index) => ({
        id: index + 1,
        members: [],
    }));

const createSourceSlots = (methodId) => {
    const bySeniority = [...SAMPLE_STUDENTS].sort((a, b) => a.seniority - b.seniority);
    const orderedStudents =
        methodId === METHODS.collegeThenSeniority
            ? COLLEGE_ORDER.flatMap((collegeKey) => bySeniority.filter((student) => student.collegeKey === collegeKey))
            : bySeniority;

    return orderedStudents.map((student, index) => ({
        slotId: `slot-${student.id}-${index + 1}`,
        student,
        collegeKey: student.collegeKey,
        state: SLOT_STATES.ready,
    }));
};

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const resetMovingOverlay = () => {
    movingOverlay.visible = false;
    movingOverlay.student = null;
    movingOverlay.top = 0;
    movingOverlay.left = 0;
    movingOverlay.width = 0;
    movingOverlay.x = 0;
    movingOverlay.y = 0;
};

const resetSimulationState = () => {
    runToken.value += 1;
    isSimulating.value = false;
    resetMovingOverlay();
    groups.value = createGroups();
    sourceSlots.value = createSourceSlots(selectedMethod.value);
};

const getSlotById = (slotId) => sourceSlots.value.find((slot) => slot.slotId === slotId);

const buildSenioritySteps = () =>
    sourceSlots.value.map((slot, index) => ({
        slotId: slot.slotId,
        groupId: (index % GROUP_COUNT) + 1,
    }));

const buildCollegeThenSenioritySteps = () => {
    const buckets = Object.fromEntries(
        COLLEGE_ORDER.map((collegeKey) => [
            collegeKey,
            sourceSlots.value.filter((slot) => slot.collegeKey === collegeKey),
        ]),
    );

    const steps = [];
    let round = 0;
    let hasMore = true;

    while (hasMore) {
        hasMore = false;

        COLLEGE_ORDER.forEach((collegeKey) => {
            const start = round * GROUP_COUNT;
            const chunk = buckets[collegeKey].slice(start, start + GROUP_COUNT);
            if (chunk.length > 0) {
                hasMore = true;
            }
            chunk.forEach((slot, index) => {
                steps.push({
                    slotId: slot.slotId,
                    groupId: index + 1,
                });
            });
        });

        round += 1;
    }

    return steps;
};

const buildSimulationSteps = () => {
    if (selectedMethod.value === METHODS.collegeThenSeniority) {
        return buildCollegeThenSenioritySteps();
    }
    return buildSenioritySteps();
};

const getTargetPosition = (groupId) => {
    const groupBody = groupBodyRefs.value.get(groupId);
    const board = boardRef.value;
    if (!groupBody || !board) {
        return null;
    }

    const groupRect = groupBody.getBoundingClientRect();
    const boardRect = board.getBoundingClientRect();
    const currentCount = groups.value[groupId - 1]?.members?.length ?? 0;

    return {
        left: groupRect.left - boardRect.left + 8,
        top: groupRect.top - boardRect.top + 10 + currentCount * (GROUP_CARD_HEIGHT + GROUP_CARD_GAP),
        width: Math.max(groupRect.width - 16, 180),
    };
};

const animateSlotToGroup = async (slot, groupId) => {
    const sourceElement = sourceSlotRefs.value.get(slot.slotId);
    const board = boardRef.value;
    if (!sourceElement || !board) {
        return;
    }

    const sourceRect = sourceElement.getBoundingClientRect();
    const boardRect = board.getBoundingClientRect();
    const target = getTargetPosition(groupId);

    if (!target) {
        return;
    }

    const startLeft = sourceRect.left - boardRect.left;
    const startTop = sourceRect.top - boardRect.top;

    movingOverlay.visible = true;
    movingOverlay.student = slot.student;
    movingOverlay.top = startTop;
    movingOverlay.left = startLeft;
    movingOverlay.width = sourceRect.width;
    movingOverlay.x = 0;
    movingOverlay.y = 0;

    await nextTick();

    slot.state = SLOT_STATES.moving;

    movingOverlay.x = target.left - startLeft;
    movingOverlay.y = target.top - startTop;
    movingOverlay.width = target.width;

    await wait(MOVE_DURATION_MS);
    resetMovingOverlay();
};

const runAutoSimulation = async () => {
    if (isManualMode.value) {
        return;
    }

    const token = ++runToken.value;
    isSimulating.value = true;

    const steps = buildSimulationSteps();

    for (const step of steps) {
        if (token !== runToken.value) {
            return;
        }

        const slot = getSlotById(step.slotId);
        if (!slot || slot.state !== SLOT_STATES.ready) {
            continue;
        }

        slot.state = SLOT_STATES.animating;
        await nextTick();

        if (token !== runToken.value) {
            return;
        }

        await animateSlotToGroup(slot, step.groupId);

        if (token !== runToken.value) {
            return;
        }

        groups.value[step.groupId - 1].members.push(slot.student);
        slot.state = SLOT_STATES.moved;

        await wait(STEP_DELAY_MS);
    }

    if (token === runToken.value) {
        isSimulating.value = false;
    }
};

const replaySimulation = async () => {
    resetSimulationState();
    await nextTick();

    if (!isManualMode.value) {
        await runAutoSimulation();
    }
};

const formatStudentNumber = (value) => String(value).padStart(2, "0");

const setSourceSlotRef = (element, slotId) => {
    if (element) {
        sourceSlotRefs.value.set(slotId, element);
    } else {
        sourceSlotRefs.value.delete(slotId);
    }
};

const setGroupBodyRef = (element, groupId) => {
    if (element) {
        groupBodyRefs.value.set(groupId, element);
    } else {
        groupBodyRefs.value.delete(groupId);
    }
};

const parseDragPayload = (event) => {
    try {
        const data = event.dataTransfer.getData("application/json");
        if (!data) {
            return dragPayload.value;
        }
        return JSON.parse(data);
    } catch (error) {
        return dragPayload.value;
    }
};

const onSourceDragStart = (event, slot) => {
    if (!isManualMode.value || slot.state !== SLOT_STATES.ready) {
        event.preventDefault();
        return;
    }

    const payload = {
        type: "source",
        slotId: slot.slotId,
        studentId: slot.student.id,
    };

    dragPayload.value = payload;
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("application/json", JSON.stringify(payload));
};

const onGroupDragStart = (event, groupId, studentId) => {
    if (!isManualMode.value) {
        event.preventDefault();
        return;
    }

    const payload = {
        type: "group",
        groupId,
        studentId,
    };

    dragPayload.value = payload;
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("application/json", JSON.stringify(payload));
};

const onGroupDragOver = (event) => {
    if (!isManualMode.value) {
        return;
    }
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
};

const onDropToGroup = (event, targetGroupId) => {
    if (!isManualMode.value) {
        return;
    }

    event.preventDefault();
    const payload = parseDragPayload(event);
    if (!payload) {
        return;
    }

    if (payload.type === "source") {
        const slot = getSlotById(payload.slotId);
        if (!slot || slot.state !== SLOT_STATES.ready) {
            return;
        }

        groups.value[targetGroupId - 1].members.push(slot.student);
        slot.state = SLOT_STATES.moved;
        dragPayload.value = null;
        return;
    }

    if (payload.type === "group") {
        if (payload.groupId === targetGroupId) {
            return;
        }

        const fromGroup = groups.value[payload.groupId - 1];
        const studentIndex = fromGroup.members.findIndex((member) => member.id === payload.studentId);
        if (studentIndex === -1) {
            return;
        }

        const [student] = fromGroup.members.splice(studentIndex, 1);
        groups.value[targetGroupId - 1].members.push(student);
        dragPayload.value = null;
    }
};

const onSelectMethod = async (methodId) => {
    if (selectedMethod.value === methodId && sourceSlots.value.length > 0) {
        return;
    }

    selectedMethod.value = methodId;
    await replaySimulation();
};

const loadAcademicLevels = async () => {
    if (!selectedAcademicLevelId.value && academicLevelOptions.value.length > 0) {
        selectedAcademicLevelId.value = academicLevelOptions.value[0].value;
    }
};

const fetchDistributionFlag = async (academicLevelId) => {
    loadingFlag.value = true;

    try {
        const flagResponse = await distributionStore.getDistributionFlag(academicLevelId);
        const apiFlag = Number(flagResponse.distributionFlag ?? METHODS.seniority);

        if ([METHODS.manual, METHODS.seniority, METHODS.collegeThenSeniority].includes(apiFlag)) {
            selectedMethod.value = apiFlag;
        } else {
            selectedMethod.value = METHODS.seniority;
        }
    } catch (error) {
        selectedMethod.value = METHODS.seniority;
    } finally {
        loadingFlag.value = false;
    }
};

const handleAcademicLevelChange = async () => {
    if (!selectedAcademicLevelId.value) {
        return;
    }

    await fetchDistributionFlag(selectedAcademicLevelId.value);
    await replaySimulation();
};

const executeDistribution = async () => {
    if (!selectedAcademicLevelId.value) {
        toast.add({
            severity: "warn",
            summary: t("sis.studentDistribution.warnings.selectLevelFirst"),
            life: 2600,
        });
        return;
    }

    try {
        await distributionStore.updateDistributionFlag(selectedAcademicLevelId.value, selectedMethod.value);
    } catch (error) {
        toast.add({
            severity: "error",
            summary: t("sis.studentDistribution.errors.executeFailed"),
            life: 2600,
        });
    }
};
</script>

